// UC Print browser artwork sync. Generated by tools/ucsync browser-assets.
// Run as a DevTools Snippet on https://undercards.net. Click the panel button.
// Downloads only the listed card/status images to the folder you choose.
// No uploads, cookie extraction, package installs, or runtime changes.

async function ucCollectAssets(config, root, io) {
  const directories=new Map();
  let ready=0,downloaded=0,reused=0;
  for(const asset of config.assets) {
    if(io.stopped())throw new Error('Stopped. Completed files are saved; run again to resume.');
    if(!/^(cards|powers)\/[A-Za-z0-9_ .()!'-]+\.(png|jpe?g)$/i.test(asset) || asset.includes('..'))throw new Error(`Invalid asset path: ${asset}`);
    const [category,name]=asset.split('/');
    if(!directories.has(category))directories.set(category,await root.getDirectoryHandle(category,{create:true}));
    const dir=directories.get(category);
    let existing;
    try {
      const handle=await dir.getFileHandle(name);
      existing=await handle.getFile();
    } catch(error) {
      if(error.name!=='NotFoundError')throw error;
    }
    let valid=false;
    if(existing) {try {await io.validate(existing);valid=true;} catch { /* Replace only after a valid download. */ }}
    if(valid) {ready++;reused++;io.progress({ready,downloaded,reused,total:config.assets.length,asset});continue;}
    io.progress({ready,downloaded,reused,total:config.assets.length,asset});
    const target=`/images/${category}/${encodeURIComponent(name)}`;
    const response=await io.fetch(target);
    if(!response.ok)throw new Error(`HTTP ${response.status}: ${target}. Your browser was also refused access. Completed files are kept; no snapshot was installed.`);
    const blob=await response.blob();
    await io.validate(blob);
    // Keep any existing file until the replacement is validated and committed.
    const handle=await dir.getFileHandle(name,{create:true});
    const writer=await handle.createWritable();
    try {await writer.write(blob);await writer.close();}
    catch(error) {try {await writer.abort();}catch {}throw error;}
    ready++;downloaded++;
    io.progress({ready,downloaded,reused,total:config.assets.length,asset});
    await io.delay();
  }
  return {ready,downloaded,reused};
}

function ucBrowserSync(config) {
  if(location.origin!=='https://undercards.net')throw new Error('Open https://undercards.net first, then run this snippet in that tab.');
  if(document.getElementById('uc-print-artwork-sync'))throw new Error('The sync panel is already open.');
  const panel=document.createElement('div');panel.id='uc-print-artwork-sync';
  Object.assign(panel.style,{position:'fixed',top:'16px',right:'16px',width:'420px',maxWidth:'90vw',padding:'20px',background:'#fff',color:'#151515',border:'3px solid #167b67',zIndex:'2147483647',font:'15px Arial',boxShadow:'0 4px 24px #0008'});
  const title=document.createElement('strong');title.textContent=`UC Print: ${config.assets.length} artwork files`;
  const status=document.createElement('p');status.style.whiteSpace='pre-wrap';status.style.overflowWrap='anywhere';
  status.textContent='Choose your JSON/assets folder. Downloads run one at a time. Keep this tab open. Valid files already saved are reused.';
  const start=document.createElement('button');start.textContent='Choose assets folder';
  const stop=document.createElement('button');stop.textContent='Stop';stop.disabled=true;
  const close=document.createElement('button');close.textContent='Close';
  let stopped=false,active=false,controller;
  stop.onclick=()=>{stopped=true;controller?.abort();};
  close.onclick=()=>{if(!active)panel.remove();};
  panel.append(title,status,start,stop,close);document.body.append(panel);
  start.onclick=async()=>{
    if(active)return;
    if(!window.showDirectoryPicker){status.textContent='Use Chrome or Edge for folder access.';return;}
    active=true;stopped=false;start.disabled=true;stop.disabled=false;close.disabled=true;
    controller=new AbortController();
    try {
      // The picker is called directly from this user click (required by browsers).
      const root=await window.showDirectoryPicker({id:'uc-print-assets',mode:'readwrite'});
      const result=await ucCollectAssets(config,root,{
        stopped:()=>stopped,
        fetch:url=>fetch(url,{credentials:'same-origin',mode:'same-origin',redirect:'error',signal:AbortSignal.any([controller.signal,AbortSignal.timeout(30000)])}),
        validate:async blob=>{
          if(!blob.size || blob.size>32*1024*1024)throw new Error('Empty or oversized artwork response.');
          const b=new Uint8Array(await blob.slice(0,8).arrayBuffer());
          const png=b.length===8 && [137,80,78,71,13,10,26,10].every((v,i)=>b[i]===v);
          const jpg=b[0]===255&&b[1]===216&&b[2]===255;
          if(!png&&!jpg)throw new Error('Expected PNG/JPG artwork; received another format (possibly an error page).');
          const image=await createImageBitmap(blob);
          const valid=image.width>0&&image.height>0&&image.width*image.height<=25000000;
          image.close();if(!valid)throw new Error('Invalid artwork dimensions.');
        },
        progress:p=>{status.textContent=`${p.ready}/${p.total} ready (${p.downloaded} downloaded, ${p.reused} reused)\n${p.asset}`;},
        delay:()=>new Promise(resolve=>setTimeout(resolve,200))
      });
      status.textContent=`SUCCESS: ${result.ready} images ready.\nNow run the offline import command in tools/ucsync/BROWSER.md. This browser helper does not install a snapshot.`;
    }catch(error){status.textContent=`STOPPED: ${error.message}\nFiles already saved are kept. You can choose the same folder to resume.`;}
    finally {active=false;start.disabled=false;stop.disabled=true;close.disabled=false;}
  };
}

